function wrU8(bytes, index) {
    return bytes[index] & 255;
}

function wrLe16(bytes, index) {
    return wrU8(bytes, index) | (wrU8(bytes, index + 1) << 8);
}

function wrLe32(bytes, index) {
    return (wrU8(bytes, index) | (wrU8(bytes, index + 1) << 8) |
        (wrU8(bytes, index + 2) << 16) | (wrU8(bytes, index + 3) << 24)) >>> 0;
}

function wrImul(a, b) {
    var ah = (a >>> 16) & 65535;
    var al = a & 65535;
    var bh = (b >>> 16) & 65535;
    var bl = b & 65535;
    return (al * bl + (((ah * bl + al * bh) & 65535) << 16)) | 0;
}

function wrCrcTable() {
    var table = [];
    for (var i = 0; i < 256; i++) {
        var value = i;
        for (var bit = 0; bit < 8; bit++) {
            value = (value >>> 1) ^ ((value & 1) ? 0xedb88320 : 0);
        }
        table[i] = value >>> 0;
    }
    return table;
}

function wrCrcStep(table, crc, value) {
    return ((crc >>> 8) ^ table[(crc ^ value) & 255]) >>> 0;
}

function wrZipCryptoDecrypt(input, password) {
    var table = wrCrcTable();
    var key0 = 0x12345678;
    var key1 = 0x23456789;
    var key2 = 0x34567890;
    function update(value) {
        key0 = wrCrcStep(table, key0, value);
        key1 = (wrImul((key1 + (key0 & 255)) | 0, 134775813) + 1) >>> 0;
        key2 = wrCrcStep(table, key2, key1 >>> 24);
    }
    var i;
    for (i = 0; i < password.length; i++) update(wrU8(password, i));
    var output = Packages.java.util.Arrays.copyOf(input, input.length);
    for (i = 0; i < input.length; i++) {
        var temp = (key2 | 2) >>> 0;
        var plain = wrU8(input, i) ^ ((wrImul(temp, temp ^ 1) >>> 8) & 255);
        output[i] = plain > 127 ? plain - 256 : plain;
        update(plain);
    }
    return output;
}

function wrDecryptZipPassword(j, src, encryptedKey) {
    var credentials = wrCredentials(src);
    var remap = j.hexDecodeToByteArray(WR_REMAP_HEX);
    var vidBytes = new Packages.java.lang.String(credentials.vid).getBytes("UTF-8");
    var keyIv = Packages.java.nio.ByteBuffer.allocate(32).array();
    for (var i = 0; i < 32; i++) {
        var mapped = wrU8(remap, wrU8(vidBytes, i % vidBytes.length));
        keyIv[i] = mapped > 127 ? mapped - 256 : mapped;
    }
    var key = Packages.java.util.Arrays.copyOfRange(keyIv, 0, 16);
    var iv = Packages.java.util.Arrays.copyOfRange(keyIv, 16, 32);
    var cipher = Packages.javax.crypto.Cipher.getInstance("AES/CBC/PKCS5Padding");
    cipher.init(
        Packages.javax.crypto.Cipher.DECRYPT_MODE,
        new Packages.javax.crypto.spec.SecretKeySpec(key, "AES"),
        new Packages.javax.crypto.spec.IvParameterSpec(iv)
    );
    return cipher.doFinal(j.base64DecodeToByteArray(String(encryptedKey)));
}

function wrInflateRaw(input) {
    var inflater = new Packages.java.util.zip.Inflater(true);
    var stream = new Packages.java.util.zip.InflaterInputStream(
        new Packages.java.io.ByteArrayInputStream(input), inflater
    );
    var output = new Packages.java.io.ByteArrayOutputStream();
    var buffer = Packages.java.nio.ByteBuffer.allocate(8192).array();
    var count;
    try {
        while ((count = stream.read(buffer)) != -1) output.write(buffer, 0, count);
        return output.toByteArray();
    } finally {
        stream.close();
        inflater.end();
        output.close();
    }
}

function wrFindEocd(bytes) {
    var minimum = Math.max(0, bytes.length - 65557);
    for (var i = bytes.length - 22; i >= minimum; i--) {
        if (wrLe32(bytes, i) == 0x06054b50) return i;
    }
    return -1;
}

function wrExtractChapterHtml(zipBytes, password, j, src, bookId, chapterUid, paragraphMarkers) {
    var eocd = wrFindEocd(zipBytes);
    if (eocd < 0) throw new Error("章节 ZIP 目录损坏");
    var entryCount = wrLe16(zipBytes, eocd + 10);
    var offset = wrLe32(zipBytes, eocd + 16);
    var parts = [];
    var infoText = "";
    var entryNames = [];
    for (var entryIndex = 0; entryIndex < entryCount; entryIndex++) {
        if (wrLe32(zipBytes, offset) != 0x02014b50) throw new Error("章节 ZIP 中央目录损坏");
        var flags = wrLe16(zipBytes, offset + 8);
        var method = wrLe16(zipBytes, offset + 10);
        var compressedSize = wrLe32(zipBytes, offset + 20);
        var nameLength = wrLe16(zipBytes, offset + 28);
        var extraLength = wrLe16(zipBytes, offset + 30);
        var commentLength = wrLe16(zipBytes, offset + 32);
        var localOffset = wrLe32(zipBytes, offset + 42);
        var nameBytes = Packages.java.util.Arrays.copyOfRange(zipBytes, offset + 46, offset + 46 + nameLength);
        var name = String(new Packages.java.lang.String(nameBytes, "UTF-8"));
        entryNames.push(name);
        if (wrLe32(zipBytes, localOffset) != 0x04034b50) throw new Error("章节 ZIP 本地目录损坏");
        var localNameLength = wrLe16(zipBytes, localOffset + 26);
        var localExtraLength = wrLe16(zipBytes, localOffset + 28);
        var dataStart = localOffset + 30 + localNameLength + localExtraLength;
        var compressed = Packages.java.util.Arrays.copyOfRange(zipBytes, dataStart, dataStart + compressedSize);
        if ((flags & 1) != 0) {
            compressed = wrZipCryptoDecrypt(compressed, password);
            if (compressed.length < 12) throw new Error("章节 ZIP 密码头损坏");
            compressed = Packages.java.util.Arrays.copyOfRange(compressed, 12, compressed.length);
        }
        var isInfo = /(^|\/)info\.txt$/i.test(name);
        var isHtml = /\.(xhtml|html|htm)$/i.test(name);
        var isText = /\.txt$/i.test(name) && !isInfo;
        var baseName = name.substring(name.lastIndexOf("/") + 1);
        var isWebNovelText = baseName && baseName.indexOf(".") < 0 && name.charAt(name.length - 1) != "/";
        if (isInfo || isHtml || isText || isWebNovelText) {
            var plain;
            if (method == 0) plain = compressed;
            else if (method == 8) plain = wrInflateRaw(compressed);
            else throw new Error("暂不支持的 ZIP 压缩方法：" + method);
            var text = String(new Packages.java.lang.String(plain, "UTF-8"));
            if (isInfo) {
                infoText = text;
            } else {
                if (isHtml) {
                    var replacements = [];
                    text = wrInsertParagraphBubbles(j, src, text, bookId, chapterUid, paragraphMarkers, replacements);
                    text = wrFilterUnsupportedFootnotes(text);
                    // Preserve the EPUB's original media tags and URLs. A Jsoup round-trip can
                    // rewrite XHTML image markup after paragraph bubbles have been inserted.
                    var bodyMatch = text.match(/<body\b[^>]*>([\s\S]*?)<\/body>/i);
                    var bodyHtml = bodyMatch ? bodyMatch[1] : text;
                    for (var replacementIndex = 0; replacementIndex < replacements.length; replacementIndex++) {
                        var replacement = replacements[replacementIndex];
                        bodyHtml = bodyHtml.split(replacement.token).join(replacement.html);
                    }
                    var textOnly = bodyHtml.replace(/<[^>]+>/g, "").replace(/&(?:nbsp|#160);/gi, " ").trim();
                    var hasMedia = /<(?:img|image|svg|video|audio)\b/i.test(bodyHtml);
                    if (textOnly || hasMedia || replacements.length) parts.push(bodyHtml);
                } else {
                    text = wrInsertParagraphBubbles(j, src, text, bookId, chapterUid, paragraphMarkers, null);
                    if (text.trim()) parts.push(text);
                }
            }
        }
        offset += 46 + nameLength + extraLength + commentLength;
    }
    if (parts.length == 0) {
        var detail = "章节包只有信息文件，账号无正文权限或登录已经失效";
        try {
            var info = infoText ? JSON.parse(infoText) : null;
            var chapter = info && info.chapters && info.chapters.length ? info.chapters[0] : null;
            if (chapter && Number(chapter.price || 0) > 0 && Number(chapter.paid || 0) == 0) {
                detail = "当前章节是付费内容，服务器没有返回正文；请确认账号已购买或具有有效会员权限";
            }
        } catch (ignoreInfoError) {}
        throw new Error(detail + "（包内文件：" + entryNames.join(", ") + "）");
    }
    return parts.join("\n");
}
function wrDownloadChapter(j, src, apiUrl) {
    apiUrl = String(apiUrl || "");
    if (apiUrl.indexOf("https://i.weread.qq.com/book/chapterdownload?") != 0) {
        throw new Error("章节下载地址无效");
    }
    var response = j.get(apiUrl, wrHeaderMap(src), 60000);
    if (response.statusCode() != 200) throw new Error("章节下载失败，HTTP " + response.statusCode());
    var encryptedKey = response.header("encryptkey");
    if (!encryptedKey) throw new Error("章节响应缺少 encryptkey");
    var bookMatch = apiUrl.match(/[?&]bookId=([^&]+)/);
    var chapterMatch = apiUrl.match(/[?&]chapters=([^&]+)/);
    var bookId = bookMatch ? decodeURIComponent(bookMatch[1]) : "";
    var chapterUid = chapterMatch ? decodeURIComponent(chapterMatch[1]) : "";
    var modes = wrCommentModes(src);
    var paragraphMarkers = modes.paragraph && bookId && chapterUid
        ? wrParagraphSummaries(j, src, bookId, chapterUid) : [];
    var password = wrDecryptZipPassword(j, src, encryptedKey);
    var html = wrExtractChapterHtml(response.bodyAsBytes(), password, j, src, bookId, chapterUid, paragraphMarkers);
    if (bookId && chapterUid && (modes.chapter || modes.book)) {
        html += wrReviewEntrySvg(j, src, bookId, chapterUid, modes);
    }
    return html;
}
