function wrParagraphSummaries(j, src, bookId, chapterUid) {
    var markers = [];
    try {
        var underlineUrl = "https://i.weread.qq.com/book/underlines?bookId=" + encodeURIComponent(bookId) +
            "&chapterUid=" + encodeURIComponent(chapterUid) + "&synckey=0";
        var response = j.get(underlineUrl, wrHeaderMap(src), 30000);
        if (Number(response.statusCode()) != 200) throw new Error("段落范围 HTTP " + response.statusCode());
        var data = JSON.parse(String(response.body()));
        var underlines = data.underlines || [];
        var seen = {};
        var requests = [];
        for (var i = 0; i < underlines.length; i++) {
            var range = String((underlines[i] || {}).range || "");
            if (!/^\d+-\d+$/.test(range) || seen[range]) continue;
            seen[range] = true;
            requests.push({count:5, range:range, synckey:0});
        }
        requests.sort(function(a, b) { return Number(a.range.split("-")[0]) - Number(b.range.split("-")[0]); });
        for (var offset = 0; offset < requests.length; offset += 10) {
            var headers = wrHeaderMap(src);
            headers.put("Content-Type", "application/json; charset=UTF-8");
            var body = JSON.stringify({
                bookId:String(bookId),
                chapterUid:isFinite(Number(chapterUid)) ? Number(chapterUid) : String(chapterUid),
                cht2sMode:"",
                reviews:requests.slice(offset, offset + 10)
            });
            var reviewResponse = j.post("https://i.weread.qq.com/book/readreviews", body, headers, 30000);
            if (Number(reviewResponse.statusCode()) != 200) throw new Error("段评摘要 HTTP " + reviewResponse.statusCode());
            var groups = JSON.parse(String(reviewResponse.body())).reviews || [];
            for (var groupIndex = 0; groupIndex < groups.length; groupIndex++) {
                var group = groups[groupIndex] || {};
                var total = Number(group.totalCount || 0);
                if (total <= 0 || !/^\d+-\d+$/.test(String(group.range || ""))) continue;
                var reviews = group.pageReviews || [];
                var hot = false;
                for (var reviewIndex = 0; reviewIndex < reviews.length; reviewIndex++) {
                    if (Number((reviews[reviewIndex] || {}).likesCount || 0) > 0) { hot = true; break; }
                }
                markers.push({range:String(group.range), total:total, hot:hot, inserted:false});
            }
        }
    } catch (error) {
        try { j.log("微信读书正文段评摘要加载失败：" + error); } catch (ignoreLog) {}
    }
    return markers;
}

function wrParagraphBubbleIndex(text, end) {
    if (!isFinite(end) || end <= 0 || end > text.length) return -1;
    var before = text.substring(0, end);
    var lastOpen = before.lastIndexOf("<");
    var lastClose = before.lastIndexOf(">");
    if (lastOpen > lastClose) return -1;
    var paragraphStart = before.toLowerCase().lastIndexOf("<p");
    if (paragraphStart >= 0) {
        var openingEnd = text.indexOf(">", paragraphStart);
        var paragraphEnd = text.toLowerCase().indexOf("</p>", end);
        var nextParagraph = text.toLowerCase().indexOf("<p", end);
        if (openingEnd >= 0 && openingEnd < end && paragraphEnd >= end &&
            (nextParagraph < 0 || paragraphEnd < nextParagraph)) return paragraphEnd;
    }
    if (/<\/?(?:html|body|p|div|span|h[1-6])\b/i.test(text)) return -1;
    var lineEnd = text.indexOf("\n", end);
    if (lineEnd < 0) return text.length;
    return lineEnd > 0 && text.charAt(lineEnd - 1) == "\r" ? lineEnd - 1 : lineEnd;
}

function wrInsertParagraphBubbles(j, src, text, bookId, chapterUid, markers, replacements) {
    text = String(text || "");
    if (!markers || !markers.length) return text;
    var grouped = {};
    for (var i = 0; i < markers.length; i++) {
        var marker = markers[i] || {};
        if (marker.inserted) continue;
        var values = String(marker.range || "").split("-");
        var end = Number(values[1]);
        var index = wrParagraphBubbleIndex(text, end);
        if (index < 0) continue;
        var key = String(index);
        if (!grouped[key]) grouped[key] = {index:index, markers:[], ranges:[], total:0};
        grouped[key].markers.push(marker);
        grouped[key].ranges.push(String(marker.range));
        grouped[key].total += Number(marker.total || 0);
    }
    var insertions = [];
    var keys = Object.keys(grouped);
    for (var groupIndex = 0; groupIndex < keys.length; groupIndex++) {
        var group = grouped[keys[groupIndex]];
        group.ranges.sort(function(a, b) { return Number(a.split("-")[0]) - Number(b.split("-")[0]); });
        var display = group.ranges.length > 1 ? "评" : (group.total > 999 ? "999+" : String(group.total));
        var rangeValue = group.ranges.join("|");
        var click = "wrOpenComments(" + JSON.stringify(String(bookId)) + "," +
            JSON.stringify(String(chapterUid)) + ",\"paragraph\"," + JSON.stringify(rangeValue) + ")";
        var image = wrCommentSvgImage(j, src, display, click, "段评 " + group.ranges.join(", "), false);
        var html = image;
        if (replacements) {
            var token = "WR_PARAGRAPH_BUBBLE_" + replacements.length + "_TOKEN";
            replacements.push({token:token, html:image, range:rangeValue, ranges:group.ranges.slice()});
            html = token;
        }
        insertions.push({index:group.index, html:html, markers:group.markers});
    }
    insertions.sort(function(a, b) { return b.index - a.index; });
    for (var insertionIndex = 0; insertionIndex < insertions.length; insertionIndex++) {
        var insertion = insertions[insertionIndex];
        text = text.substring(0, insertion.index) + insertion.html + text.substring(insertion.index);
        for (var markerIndex = 0; markerIndex < insertion.markers.length; markerIndex++) {
            insertion.markers[markerIndex].inserted = true;
        }
    }
    return text;
}
