function wrReviewRecords(payload) {
    var reviews = payload && payload.reviews ? payload.reviews : [];
    var records = [];
    var seen = {};
    for (var i = 0; i < reviews.length; i++) {
        var item = reviews[i] || {};
        var wrapper = item;
        var review = item.review && typeof item.review == "object" ? item.review : item;
        if (review.review && typeof review.review == "object") review = review.review;
        var id = String(wrapper.reviewId || review.reviewId || i);
        if (seen[id]) continue;
        seen[id] = true;
        records.push({wrapper: wrapper, review: review});
    }
    return records;
}

function wrParagraphRecords(payload) {
    var groups = payload && payload.reviews ? payload.reviews : [];
    var records = [];
    var seen = {};
    for (var i = 0; i < groups.length; i++) {
        var group = groups[i] || {};
        var pageReviews = group.pageReviews || [];
        var range = String(group.range || "");
        var rangeTotal = Number(group.totalCount || 0);
        for (var j = 0; j < pageReviews.length; j++) {
            var item = pageReviews[j] || {};
            var review = item.review || item;
            var id = String(item.reviewId || review.reviewId || (i + "-" + j));
            if (seen[id]) continue;
            seen[id] = true;
            records.push({wrapper:item, review:review, range:range || String(review.range || ""),
                rangeTotal:rangeTotal, rangeMaxIdx:Number(group.maxIdx || 0),
