function wrLoadReviewReplies(j, src, records, maxReviews) {
    var loadedReviews = 0;
    maxReviews = Number(maxReviews || 5);
    for (var i = 0; i < records.length && loadedReviews < maxReviews; i++) {
        var record = records[i] || {};
        var wrapper = record.wrapper || {};
        var review = record.review || {};
        var reviewId = String(wrapper.reviewId || review.reviewId || "");
        var total = Number(wrapper.commentsCount || review.commentsCount || 0);
        var current = wrapper.hotComments || review.hotComments || [];
        if (!reviewId || total <= current.length) continue;
        var replies = [];
        var seen = {};
        for (var oldIndex = 0; oldIndex < current.length; oldIndex++) {
            var oldReply = current[oldIndex] || {};
            var oldId = String(oldReply.commentId || oldReply.reviewId || oldIndex);
            if (!seen[oldId]) { seen[oldId] = true; replies.push(oldReply); }
        }
        var cursor = 0;
        for (var page = 0; page < 3; page++) {
            try {
                var url = "https://i.weread.qq.com/review/commentloadmore?reviewId=" + encodeURIComponent(reviewId) +
                    "&maxIdx=" + cursor + "&count=100&isExpandAll=0";
                var response = j.get(url, wrHeaderMap(src), 30000);
                if (response.statusCode() != 200) break;
                var data = JSON.parse(String(response.body()));
                var comments = data.comments || [];
                var added = 0;
                for (var replyIndex = 0; replyIndex < comments.length; replyIndex++) {
                    var reply = comments[replyIndex] || {};
                    var id = String(reply.commentId || reply.reviewId || (cursor + replyIndex));
                    if (!seen[id]) { seen[id] = true; replies.push(reply); added++; }
                }
                if (!data.commentsHasMore || !comments.length || !added) break;
                cursor += comments.length;
            } catch (replyError) {
                try { j.log("微信读书回复加载失败：" + replyError); } catch (ignoreReplyLog) {}
                break;
            }
        }
        wrapper.hotComments = replies;
        loadedReviews++;
    }
    return loadedReviews;
}
function wrCommentCards(records, emptyText, sectionIndex) {
