        var content = review.content || review.htmlContent || review.abstract || review.title || "";
        var context = review.abstract || review.contextAbstract || "";
        var rangeValue = String(record.range || review.range || "");
        var rangeHeading = "";
        if (rangeValue && rangeValue != lastRange) {
            lastRange = rangeValue;
