            rangeHeading = "<div class='range-heading'><div><strong>正文位置 " +
                wrEscapeHtml(rangeValue) + "</strong>" + (rangeTotal > 0 ? "<span>本段共 " + rangeTotal + " 条段评</span>" : "") +
                "</div>" + (context ? "<p>" + wrEscapeHtml(context) + "</p>" : "") + "</div>";
        }
        var created = "";
        if (Number(review.createTime) > 0) {
            var date = new Date(Number(review.createTime) * 1000);
            created = date.getFullYear() + "-" + (date.getMonth() + 1) + "-" + date.getDate();
        }
