        if (review.chapterName || review.chapterTitle) meta.push(String(review.chapterName || review.chapterTitle));
        var badges = [];
        if (review.isAuthorComment) badges.push("作者回复");
        if (review.isAuthorLike) badges.push("作者赞过");
        if (author.isDeepV) badges.push(author.deepVTitle || "资深读者");
        var badgeHtml = [];
        for (var badgeIndex = 0; badgeIndex < badges.length; badgeIndex++) {
            badgeHtml.push("<span class='badge'>" + wrEscapeHtml(badges[badgeIndex]) + "</span>");
        }
        var scoreHtml = "";
        if (Number(review.star || 0) > 0) {
            var score = Math.round(Number(review.star) / 20 * 10) / 10;
            scoreHtml = "<span class='score'>" + score + " 分</span>";
        }
        var extra = "";
        if (!rangeHeading && context && context != content) extra = "<blockquote>" + wrEscapeHtml(context) + "</blockquote>";
        var pictures = review.pictures || wrapper.pictures || [];
        var pictureHtml = [];
        for (var pictureIndex = 0; pictureIndex < pictures.length; pictureIndex++) {
            var picture = pictures[pictureIndex] || {};
            var pictureUrl = String(picture.url || "");
            if (/^https:\/\//i.test(pictureUrl)) {
