                    wrEscapeHtml(pictureUrl) + "' alt='评论图片'>");
            }
        }
        var replies = wrapper.hotComments || review.hotComments || [];
        var replyHtml = [];
        for (var replyIndex = 0; replyIndex < replies.length; replyIndex++) {
            var reply = replies[replyIndex] || {};
            var replyAuthor = reply.author || {};
            replyHtml.push("<div class='reply'><b>" + wrEscapeHtml(replyAuthor.name || replyAuthor.nick || "回复") + "</b>：" +
                wrEscapeHtml(reply.content || "") + "</div>");
        }
        cards.push("<article class='comment-item" + (i >= 20 ? " batch-hidden" : "") + "'>" + rangeHeading + "<header>" + avatar + "<div class='identity'><div><strong>" + wrEscapeHtml(authorName) +
            "</strong>" + badgeHtml.join("") + "</div><span>" + wrEscapeHtml(created) + "</span></div>" +
            scoreHtml + "</header>" + extra + "<div class='content'>" +
            wrEscapeHtml(content).replace(/\r?\n/g, "<br>") + "</div>" + pictureHtml.join("") + replyHtml.join("") +
            "<footer>" + wrEscapeHtml(meta.join(" · ")) + (meta.length ? "　" : "") +
            "赞 " + likes + "　回复 " + comments + "</footer></article>");
    }
    if (cards.length == 0) cards.push("<div class='empty'>" + wrEscapeHtml(emptyText || "暂时没有可显示的评论") + "</div>");
    return cards.join("");
