    var newDeviceId = wrInputValue(data, "_wrNewDeviceId") || wrValue(src, "_wrNewDeviceId");
    if (!/^\d{28}$/.test(oldDeviceId)) oldDeviceId = wrRandomDigits(random, 28);
    if (!/^\d{28}$/.test(installId)) installId = wrRandomDigits(random, 28);
    if (!/^\d{38}$/.test(newDeviceId)) newDeviceId = wrRandomDigits(random, 38);
    return {
