}

function wrBytes(values) {
    var bytes = Packages.java.nio.ByteBuffer.allocate(values.length).array();
    for (var i = 0; i < values.length; i++) {
        var value = values[i] & 255;
        bytes[i] = value > 127 ? value - 256 : value;
    }
    return bytes;
}

function wrUtf8Values(value) {
    var bytes = new Packages.java.lang.String(String(value)).getBytes("UTF-8");
    var values = [];
    for (var i = 0; i < bytes.length; i++) values.push(wrU8(bytes, i));
    return values;
}

function wrRemapValues(j, value) {
    var table = j.hexDecodeToByteArray(WR_REMAP_HEX);
    var input = new Packages.java.lang.String(String(value)).getBytes("UTF-8");
    var output = [];
    for (var i = 0; i < input.length; i++) output.push(wrU8(table, wrU8(input, i)));
    return output;
}

function wrCompareBytes(left, right) {
    var length = Math.min(left.length, right.length);
    for (var i = 0; i < length; i++) {
        if (left[i] != right[i]) return left[i] - right[i];
    }
    return left.length - right.length;
}

function wrRotateByXor(values) {
    if (values.length == 0) return [];
    var xor = 0;
    for (var i = 0; i < values.length; i++) xor ^= values[i];
    var shift = xor % 11;
    var output = [];
    for (i = 0; i < values.length; i++) output[(i + shift) % values.length] = values[i];
    return output;
}

function wrSha256Hex(values) {
    var digest = Packages.java.security.MessageDigest.getInstance("SHA-256").digest(wrBytes(values));
    var hex = "";
    for (var i = 0; i < digest.length; i++) {
        var item = (wrU8(digest, i)).toString(16);
        hex += item.length == 1 ? "0" + item : item;
    }
    return hex;
}

function wrGuestSignature(j, token, random, timestamp, oldDeviceId) {
    var parts = [
        wrRemapValues(j, token),
        wrRemapValues(j, String(random)),
        wrRemapValues(j, String(timestamp)),
        wrRemapValues(j, oldDeviceId),
        wrUtf8Values("5a6f1")
    ];
    parts.sort(wrCompareBytes);
    var joined = [];
    for (var i = 0; i < parts.length; i++) joined = joined.concat(parts[i]);
    var first = wrSha256Hex(wrRotateByXor(joined));
    return wrSha256Hex(wrRotateByXor(wrUtf8Values(first)));
}

function wrLoginSignature(timestamp, deviceId, random) {
    return wrSha256Hex(wrUtf8Values(String(timestamp) + deviceId + String(random)));
}

function wrResponseJson(response, label, allowedStatus) {
