function wrSaveQrLogin(j, src, input, state, userAgent, loginData) {
    var saved = {
        "vid": String(loginData.vid),
        "accessToken": String(loginData.accessToken),
        "User-Agent": userAgent,
        "段评开关": wrInputToggle(input, src, "段评开关", "🔳"),
        "章评开关": wrInputToggle(input, src, "章评开关", "🔳"),
        "书评开关": wrInputToggle(input, src, "书评开关", "🔳"),
        "_wrLoginMode": "wechat",
        "_wrOldDeviceId": state.oldDeviceId,
        "_wrInstallId": state.installId,
        "_wrNewDeviceId": state.newDeviceId
    };
    if (loginData.refreshToken) saved._wrRefreshToken = String(loginData.refreshToken);
    wrApplyCommentPreferences(input, src, saved);
    if (!src.putLoginInfo(JSON.stringify(saved))) throw new Error("微信扫码登录参数保存失败");
    src.putLoginHeader(JSON.stringify({
        "vid": saved.vid,
        "accessToken": saved.accessToken,
        "User-Agent": saved["User-Agent"],
        "baseapi": "36",
        "appver": WR_APP_VERSION,
        "basever": WR_APP_VERSION,
        "osver": "16",
        "channelId": "0"
    }));
    j.upLoginData(wrMap(saved));
    if (wrValue(src, "vid") !== saved.vid || wrValue(src, "accessToken") !== saved.accessToken ||
        wrValue(src, "User-Agent") !== saved["User-Agent"]) {
        throw new Error("微信扫码登录参数写入后读取不一致");
    }
    return saved;
}
function wrQrLogin(j, src, input) {
    var userAgent = wrInputValue(input, "User-Agent") || wrValue(src, "User-Agent") || WR_DEFAULT_USER_AGENT;
    var state = wrDeviceState(src, input);
    var loginHeaders = wrLoginHeaderMap(userAgent, "", "");
    j.longToast("正在获取微信登录二维码...");
    var wxTicket = wrResponseJson(
        j.get("https://i.weread.qq.com/wxticket?nonceStr=weread", loginHeaders, 30000),
        "微信二维码票据"
    ).data;
    if (!wxTicket.signature || !wxTicket.timeStamp) throw new Error("微信二维码票据不完整");
    var qrUrl = "https://open.weixin.qq.com/connect/sdk/qrconnect?appid=" + WR_WECHAT_APP_ID +
        "&noncestr=weread&timestamp=" + wxTicket.timeStamp +
        "&scope=snsapi_userinfo%2Csnsapi_timeline%2Csnsapi_friend&signature=" + wxTicket.signature;
    var qrData = wrResponseJson(j.get(qrUrl, new Packages.java.util.HashMap(), 30000), "微信二维码").data;
    if (Number(qrData.errcode) != 0 || !qrData.uuid || !qrData.qrcode || !qrData.qrcode.qrcodebase64) {
        throw new Error("微信二维码生成失败，错误码 " + qrData.errcode);
    }
    var qrBase64 = String(qrData.qrcode.qrcodebase64 || "").replace(/^data:image\/[a-zA-Z0-9.+-]+;base64,/, "").replace(/\s/g, "");
    if (!qrBase64) throw new Error("微信二维码图片为空");
    var qrMime = qrBase64.indexOf("/9j/") == 0 ? "image/jpeg" :
        (qrBase64.indexOf("iVBOR") == 0 ? "image/png" :
        (qrBase64.indexOf("UklGR") == 0 ? "image/webp" : "image/jpeg"));
    var qrCacheKey = "wr_qr_code_" + String(qrData.uuid);
    try { cache.deleteMemory(qrCacheKey); } catch (ignoreOldQrCache) {}
    var qrPage = null, qrAwaitError = null;
    try {
        qrPage = j.startBrowserAwait("https://long.open.weixin.qq.com/", "微信扫码登录", false,
            wrQrHtml(qrBase64, qrMime, qrData.uuid, qrCacheKey));
    } catch (awaitError) {
        qrAwaitError = awaitError;
    }
    var encodedCode = "";
    try {
        encodedCode = String(cache.getFromMemory(qrCacheKey) || "").trim();
        cache.deleteMemory(qrCacheKey);
    } catch (ignoreQrCache) {}
    var qrHtml = "";
    if (qrPage != null) {
        try {
            var qrBody = qrPage.body;
            if (typeof qrBody == "function") qrBody = qrPage.body();
            qrHtml = String(qrBody || "");
        } catch (ignoreQrBody) {}
    }
    if (!encodedCode) {
        var codeMatch = qrHtml.match(/data-wr-code=[\"']([^\"']+)/i) ||
            qrHtml.match(/id=[\"']wr-qr-result[\"'][^>]*data-result=[\"']([^\"']+)/i) ||
            qrHtml.match(/id=[\"']wr-qr-result[\"'][^>]*>([^<]+)/i);
        if (codeMatch && codeMatch[1]) encodedCode = String(codeMatch[1]).trim();
    }
    if (!encodedCode) {
        var awaitDetail = qrAwaitError && qrAwaitError.message ? "：" + qrAwaitError.message : "";
        throw new Error("未取得微信确认结果" + awaitDetail + "。请确认页面显示微信已确认后再返回");
    }
    var wxCode = String(new Packages.java.lang.String(j.base64DecodeToByteArray(encodedCode), "UTF-8"));
    if (!wxCode) throw new Error("微信确认结果为空");
    j.longToast("已取得微信确认，正在换取正式登录参数...");

    var loginTimestamp = Number(Packages.java.lang.System.currentTimeMillis());
    var loginRandom = state.random.nextInt(1000);
    var loginBody = {
        appFirstInstall: 0,
        code: wxCode,
        deviceId: state.newDeviceId,
        deviceName: "xiaomi",
        deviceType: 1,
        installId: state.installId,
        isAutoLogout: 0,
        isFromQrcode: 1,
        random: loginRandom,
        signature: wrLoginSignature(loginTimestamp, state.newDeviceId, loginRandom),
        timestamp: loginTimestamp,
        trackId: "",
        virtualChannelId: "",
        wxToken: 1
    };
    var loginData = wrResponseJson(
        j.post("https://i.weread.qq.com/login", JSON.stringify(loginBody), loginHeaders, 30000),
        "微信读书正式登录"
    ).data;
    if (loginData.vid == null || !loginData.accessToken) throw new Error("正式登录没有返回 vid/accessToken");
    var saved = wrSaveQrLogin(j, src, input, state, userAgent, loginData);
    var message = "微信扫码登录成功，正式 APP 登录态和 refreshToken 已保存";
    j.upLoginData(wrMap({vid:saved.vid, accessToken:saved.accessToken, "User-Agent":saved["User-Agent"],
        "微信扫码登录":"微信扫码登录成功"}));
    try { j.toast(message); } catch (ignoreShortToast) {}
    j.longToast(message);
    return message;
}
function wrSaveManualLogin(j, src, input) {
    var vid = wrInputValue(input, "vid");
    var accessToken = wrInputValue(input, "accessToken");
    var userAgent = wrInputValue(input, "User-Agent") || WR_DEFAULT_USER_AGENT;
    if (!vid || !accessToken) throw new Error("抓包登录请填写 vid 和 accessToken；也可以改用游客或微信扫码登录");
    var saved = {
        "vid": vid,
        "accessToken": accessToken,
        "User-Agent": userAgent,
        "小说章节书评入口": wrInputValue(input, "小说章节书评入口") || wrValue(src, "小说章节书评入口") || "关闭",
        "段评开关": wrInputToggle(input, src, "段评开关", "关闭"),
        "章评开关": wrInputToggle(input, src, "章评开关", "关闭"),
        "书评开关": wrInputToggle(input, src, "书评开关", "关闭"),
        "作者评论开关": wrInputToggle(input, src, "作者评论开关", "关闭"),
        "_wrLoginMode": "capture"
    };
    var hiddenNames = ["_wrOldDeviceId", "_wrInstallId", "_wrNewDeviceId", "_wrRefreshToken",
        "_wrGuestVid", "_wrGuestAccessToken", "_wrCaptchaTicket", "_wrCaptchaRandstr", "_wrCaptchaSavedAt"];
    for (var i = 0; i < hiddenNames.length; i++) {
        var hiddenValue = wrInputValue(input, hiddenNames[i]) || wrValue(src, hiddenNames[i]);
        if (hiddenValue) saved[hiddenNames[i]] = hiddenValue;
    }
    wrApplyCommentPreferences(input, src, saved);
    src.putLoginInfo(JSON.stringify(saved));
    j.upLoginData(wrMap(saved));
    return wrCheckLogin(j, src);
}

