function wrLoginAction(name, action) {
    try {
        return action();
    } catch (error) {
        var detail = error && error.message ? String(error.message) : String(error);
        var message = name + "失败：" + detail;
        java.longToast(message);
        return message;
    }
}
function login() { return wrLoginAction("抓包参数登录", function() { return wrSaveManualLogin(java, source, result); }); }
