ruleBookInfo.init:
@js:
var root = JSON.parse(result);
var out = {};
if (root.albumInfo) {
    var album = root.albumInfo;
    book.type = 32;
    out._media = "audio";
    out.name = album.name;
    out.author = album.authorName || album.bookAuthor;
    out.intro = album.intro;
    out.kind = album.themeTag || "听书";
    out.cover = album.cover;
    out.wordCount = String(album.trackCount || "") + "集";
    out.lastChapter = album.firstTrackTitle;
    out.updateTime = album.updateTime;
    out.tocUrl = "https://i.weread.qq.com/album/list?albumId=" + album.albumId + "&synckey=0";
} else {
    book.type = 8;
    out._media = "novel";
    out.name = root.title;
    out.author = root.author;
    out.intro = root.intro;
    out.kind = root.category;
    out.cover = root.cover;
    out.wordCount = root.totalWords;
    out.lastChapter = root.lastChapterIdx;
    out.updateTime = root.updateTime;
    var body = JSON.stringify({bookIds:[String(root.bookId)], synckeys:[0], teenmode:0});
    out.tocUrl = "https://i.weread.qq.com/book/chapterInfos," + JSON.stringify({
        method:"POST", body:body, headers:{"Content-Type":"application/json"}
    });
}
JSON.stringify(out);

