@js:
var media = java.getString("$._media");
if (media == "audio") {
    var trackId = java.getString("$.trackId");
    "https://i.weread.qq.com/getplayinfo?trackId=" + java.encodeURI(trackId) + "&type=0&quality=0";
} else {
    var bookId = java.getString("$._bookId");
    var chapterUid = java.getString("$.chapterUid");
    var bookVersion = java.getString("$._synckey");
    var bookType = java.getString("$._format") || "epub";
    var apiUrl = "https://i.weread.qq.com/book/chapterdownload?bookId=" + java.encodeURI(bookId) +
        "&chapters=" + java.encodeURI(chapterUid) +
        "&pf=wechat_wx-2001-android-100-weread&pfkey=pfKey&zoneId=1" +
        "&bookVersion=" + java.encodeURI(bookVersion) +
        "&bookType=" + java.encodeURI(bookType) +
        "&quote=&release=1&stopAutoPayWhenBNE=0&preload=2&preview=0&offline=0" +
        "&giftPayingCard=0&enVersion=10.2.1&modernVersion=10.2.1&teenmode=0";
